import { GoogleGenAI, Modality } from "@google/genai";

const getAi = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeRounds = async (rounds: any[]) => {
  const ai = getAi();
  const prompt = `Analyze the following nursing tracer rounds data and provide a concise summary of strengths, major development areas (weaknesses), and 3 specific actionable recommendations for the nursing department. 
  Data: ${JSON.stringify(rounds)}`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      temperature: 0.7,
    }
  });

  return response.text;
};

export const chatWithAssistant = async (history: { role: string; content: string }[], message: string) => {
  const ai = getAi();
  const chat = ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: "You are a specialized clinical nursing audit assistant. Your role is to help nurses interpret tracer round data, suggest improvements based on JCI or hospital standards, and answer clinical documentation questions. Be professional, encouraging, and accurate.",
    }
  });

  // Sending history as messages is handled slightly differently in this SDK version
  // but we can simulate a flow for a simple web interface
  const response = await chat.sendMessage({ message });
  return response.text;
};

// TTS Implementation logic
export const speakText = async (text: string) => {
  const ai = getAi();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) return;

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const audioBytes = decodeBase64(base64Audio);
    const audioBuffer = await decodeAudioData(audioBytes, audioContext, 24000, 1);

    const source = audioContext.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(audioContext.destination);
    source.start();
  } catch (error) {
    console.error("TTS Error:", error);
  }
};

// Audio helper functions
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState } from 'react';
import { 
  MONTHS, 
  DEPARTMENTS, 
  RN_LEVELS, 
  SPECIALTIES, 
  SECTIONS_CONFIG 
} from '../constants';
import { ComplianceStatus, TracerRound, SectionData } from '../types';
import { Save, ChevronRight, ChevronLeft, PlusCircle } from 'lucide-react';

interface TracerFormProps {
  onSubmit: (data: TracerRound) => void;
}

const TracerForm: React.FC<TracerFormProps> = ({ onSubmit }) => {
  const [step, setStep] = useState(0);
  const [formData, setFormData] = useState<Partial<TracerRound>>({
    year: new Date().getFullYear(),
    month: MONTHS[new Date().getMonth()],
    date: new Date().toISOString().split('T')[0],
    sourceOfData: '',
    department: DEPARTMENTS[0],
    rnLevel: RN_LEVELS[0],
    principalDiagnosis: '',
    comorbidity: '',
    specialty: SPECIALTIES[0],
    patientAge: 0,
    sections: SECTIONS_CONFIG.reduce((acc, section) => {
      acc[section.id as keyof TracerRound['sections']] = {
        items: section.items.reduce((itemAcc, item) => {
          itemAcc[item.id] = ComplianceStatus.MET;
          return itemAcc;
        }, {} as Record<string, ComplianceStatus>),
        finding: ''
      };
      return acc;
    }, {} as TracerRound['sections']),
    developmentIssues: '',
    appreciations: ''
  });

  const handleBasicInfoChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: name === 'year' || name === 'patientAge' ? parseInt(value) : value }));
  };

  const handleStatusChange = (sectionId: string, itemId: string, status: ComplianceStatus) => {
    setFormData(prev => {
      const sections = { ...prev.sections } as TracerRound['sections'];
      sections[sectionId as keyof TracerRound['sections']].items[itemId] = status;
      return { ...prev, sections };
    });
  };

  const handleFindingChange = (sectionId: string, finding: string) => {
    setFormData(prev => {
      const sections = { ...prev.sections } as TracerRound['sections'];
      sections[sectionId as keyof TracerRound['sections']].finding = finding;
      return { ...prev, sections };
    });
  };

  const handleFinalSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalData: TracerRound = {
      ...formData as TracerRound,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    onSubmit(finalData);
  };

  const steps = [
    { title: 'Demographics', content: (
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium text-gray-700">Year</label>
          <input type="number" name="year" value={formData.year} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 bg-white border" />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700">Month</label>
          <select name="month" value={formData.month} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 bg-white border">
            {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700">Date</label>
          <input type="date" name="date" value={formData.date} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 bg-white border" />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700">Department</label>
          <select name="department" value={formData.department} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 bg-white border">
            {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
        <div className="md:col-span-2">
          <label className="block text-sm font-medium text-gray-700">Principal Diagnosis</label>
          <input type="text" name="principalDiagnosis" value={formData.principalDiagnosis} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 bg-white border" />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700">RN Level</label>
          <select name="rnLevel" value={formData.rnLevel} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 bg-white border">
            {RN_LEVELS.map(l => <option key={l} value={l}>{l}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700">Patient Age</label>
          <input type="number" name="patientAge" value={formData.patientAge} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 bg-white border" />
        </div>
      </div>
    )},
    ...SECTIONS_CONFIG.map(section => ({
      title: section.title,
      content: (
        <div className="space-y-6">
          <div className="bg-blue-50 p-4 rounded-lg flex items-center gap-2 mb-4">
            {section.icon}
            <h3 className="font-semibold text-blue-800">{section.title}</h3>
          </div>
          {section.items.map(item => (
            <div key={item.id} className="flex flex-col md:flex-row md:items-center justify-between p-3 border-b border-gray-100 last:border-0 hover:bg-gray-50 transition-colors">
              <span className="text-sm text-gray-700 font-medium mb-2 md:mb-0">{item.id} {item.label}</span>
              <div className="flex gap-2">
                {[ComplianceStatus.MET, ComplianceStatus.NOT_MET, ComplianceStatus.NA].map(status => (
                  <button
                    key={status}
                    type="button"
                    onClick={() => handleStatusChange(section.id, item.id, status)}
                    className={`px-3 py-1 text-xs font-semibold rounded-full border transition-all ${
                      formData.sections?.[section.id as keyof TracerRound['sections']]?.items[item.id] === status
                        ? status === ComplianceStatus.MET ? 'bg-green-100 text-green-700 border-green-200' :
                          status === ComplianceStatus.NOT_MET ? 'bg-red-100 text-red-700 border-red-200' :
                          'bg-gray-200 text-gray-700 border-gray-300'
                        : 'bg-white text-gray-400 border-gray-200 hover:border-indigo-300'
                    }`}
                  >
                    {status}
                  </button>
                ))}
              </div>
            </div>
          ))}
          <div className="mt-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">Findings / Comments for this section</label>
            <textarea
              value={formData.sections?.[section.id as keyof TracerRound['sections']]?.finding}
              onChange={(e) => handleFindingChange(section.id, e.target.value)}
              className="w-full h-24 p-3 border rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
              placeholder="Record any specific observations..."
            />
          </div>
        </div>
      )
    })),
    { title: 'Summary & Issues', content: (
      <div className="space-y-6">
        <div>
          <label className="block text-sm font-medium text-gray-900 mb-2 font-bold text-red-600">Development Issues (Areas for Improvement)</label>
          <textarea
            name="developmentIssues"
            value={formData.developmentIssues}
            onChange={handleBasicInfoChange}
            className="w-full h-32 p-3 border rounded-lg focus:ring-2 focus:ring-red-500 outline-none"
            placeholder="List issues identified during round..."
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-900 mb-2 font-bold text-green-600">Appreciations (Commendations)</label>
          <textarea
            name="appreciations"
            value={formData.appreciations}
            onChange={handleBasicInfoChange}
            className="w-full h-32 p-3 border rounded-lg focus:ring-2 focus:ring-green-500 outline-none"
            placeholder="Highlight good practices observed..."
          />
        </div>
      </div>
    )}
  ];

  return (
    <div className="max-w-4xl mx-auto bg-white rounded-xl shadow-lg overflow-hidden">
      <div className="bg-indigo-600 p-6 text-white">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <PlusCircle /> New Tracer Round
          </h2>
          <span className="text-sm bg-indigo-500 px-3 py-1 rounded-full">
            Step {step + 1} of {steps.length}
          </span>
        </div>
        <div className="w-full bg-indigo-800 h-2 rounded-full overflow-hidden">
          <div 
            className="bg-indigo-300 h-full transition-all duration-300" 
            style={{ width: `${((step + 1) / steps.length) * 100}%` }}
          />
        </div>
      </div>

      <div className="p-8">
        <h3 className="text-lg font-semibold text-gray-800 mb-6">{steps[step].title}</h3>
        {steps[step].content}

        <div className="mt-10 flex justify-between">
          <button
            type="button"
            onClick={() => setStep(s => Math.max(0, s - 1))}
            disabled={step === 0}
            className={`flex items-center gap-1 px-4 py-2 rounded-lg font-medium transition-all ${
              step === 0 ? 'text-gray-300' : 'text-gray-600 hover:bg-gray-100'
            }`}
          >
            <ChevronLeft size={18} /> Previous
          </button>

          {step < steps.length - 1 ? (
            <button
              type="button"
              onClick={() => setStep(s => s + 1)}
              className="flex items-center gap-1 px-6 py-2 bg-indigo-600 text-white rounded-lg font-medium hover:bg-indigo-700 transition-all shadow-md"
            >
              Next <ChevronRight size={18} />
            </button>
          ) : (
            <button
              type="button"
              onClick={handleFinalSubmit}
              className="flex items-center gap-1 px-8 py-2 bg-green-600 text-white rounded-lg font-bold hover:bg-green-700 transition-all shadow-lg"
            >
              <Save size={18} /> Save Record
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default TracerForm;

import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Legend,
  PieChart, Pie, Cell
} from 'recharts';
import { TracerRound, ComplianceStatus } from '../types';
import { SECTIONS_CONFIG } from '../constants';
import { AlertCircle, CheckCircle, TrendingUp } from 'lucide-react';

interface DashboardProps {
  rounds: TracerRound[];
}

const Dashboard: React.FC<DashboardProps> = ({ rounds }) => {
  const stats = useMemo(() => {
    if (rounds.length === 0) return null;

    const sectionCompliance = SECTIONS_CONFIG.map(section => {
      let totalItems = 0;
      let metItems = 0;

      rounds.forEach(round => {
        const sData = round.sections[section.id as keyof TracerRound['sections']];
        Object.values(sData.items).forEach(status => {
          if (status !== ComplianceStatus.NA) {
            totalItems++;
            if (status === ComplianceStatus.MET) metItems++;
          }
        });
      });

      return {
        name: section.title.split('. ')[1],
        compliance: totalItems > 0 ? Math.round((metItems / totalItems) * 100) : 0,
        fullTitle: section.title
      };
    });

    const overallCompliance = Math.round(
      sectionCompliance.reduce((acc, curr) => acc + curr.compliance, 0) / sectionCompliance.length
    );

    return { sectionCompliance, overallCompliance };
  }, [rounds]);

  if (!stats) {
    return (
      <div className="flex flex-col items-center justify-center h-96 bg-white rounded-xl shadow-sm border border-dashed border-gray-300">
        <TrendingUp className="w-12 h-12 text-gray-300 mb-2" />
        <p className="text-gray-500 font-medium">No data recorded yet. Start by creating a new round.</p>
      </div>
    );
  }

  const COLORS = ['#4f46e5', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4'];

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-gray-500 uppercase">Total Rounds</p>
            <p className="text-3xl font-bold text-gray-900">{rounds.length}</p>
          </div>
          <div className="p-3 bg-indigo-50 rounded-lg text-indigo-600">
            <CheckCircle className="w-8 h-8" />
          </div>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-gray-500 uppercase">Avg Compliance</p>
            <p className="text-3xl font-bold text-gray-900">{stats.overallCompliance}%</p>
          </div>
          <div className="p-3 bg-green-50 rounded-lg text-green-600">
            <TrendingUp className="w-8 h-8" />
          </div>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-gray-500 uppercase">Critical Sections</p>
            <p className="text-3xl font-bold text-gray-900">
              {stats.sectionCompliance.filter(s => s.compliance < 80).length}
            </p>
          </div>
          <div className="p-3 bg-red-50 rounded-lg text-red-600">
            <AlertCircle className="w-8 h-8" />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-bold text-gray-800 mb-6">Compliance per Topic (%)</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={stats.sectionCompliance} layout="vertical">
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                <XAxis type="number" domain={[0, 100]} hide />
                <YAxis dataKey="name" type="category" width={120} tick={{ fontSize: 12, fill: '#64748b' }} />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="compliance" radius={[0, 4, 4, 0]}>
                  {stats.sectionCompliance.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-bold text-gray-800 mb-6">Quality Radar</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <RadarChart cx="50%" cy="50%" outerRadius="80%" data={stats.sectionCompliance}>
                <PolarGrid stroke="#e2e8f0" />
                <PolarAngleAxis dataKey="name" tick={{ fontSize: 10, fill: '#64748b' }} />
                <PolarRadiusAxis angle={30} domain={[0, 100]} />
                <Radar
                  name="Compliance"
                  dataKey="compliance"
                  stroke="#4f46e5"
                  fill="#4f46e5"
                  fillOpacity={0.6}
                />
              </RadarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

