import React, { useState, useRef, useEffect } from 'react';
import { 
  chatWithAssistant, 
  analyzeRounds, 
  speakText 
} from '../services/geminiService';
import { TracerRound, ChatMessage } from '../types';
import { 
  Send, 
  Sparkles, 
  Volume2, 
  User, 
  Bot, 
  Loader2,
  BrainCircuit,
  Maximize2,
  Minimize2
} from 'lucide-react';

interface AssistantProps {
  rounds: TracerRound[];
}

const Assistant: React.FC<AssistantProps> = ({ rounds }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isExpanded, setIsExpanded] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', content: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const response = await chatWithAssistant(messages, input);
      setMessages(prev => [...prev, { role: 'model', content: response }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', content: "Sorry, I'm having trouble connecting right now." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleAnalyze = async () => {
    if (rounds.length === 0 || isAnalyzing) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeRounds(rounds);
      setAnalysis(result);
    } catch (error) {
      console.error(error);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleSpeak = (text: string) => {
    speakText(text);
  };

  return (
    <div className={`grid grid-cols-1 ${isExpanded ? 'lg:grid-cols-1' : 'lg:grid-cols-3'} gap-6 transition-all duration-300`}>
      {/* AI Insights Card */}
      <div className={`${isExpanded ? 'hidden' : 'lg:col-span-1'} bg-white rounded-xl shadow-lg flex flex-col h-[600px] border border-indigo-100`}>
        <div className="p-4 bg-indigo-600 rounded-t-xl text-white flex items-center justify-between">
          <h3 className="font-bold flex items-center gap-2">
            <BrainCircuit size={18} /> Deep Insights
          </h3>
          <button 
            onClick={handleAnalyze} 
            disabled={isAnalyzing || rounds.length === 0}
            className="text-xs bg-indigo-500 hover:bg-indigo-400 p-1 rounded disabled:opacity-50"
          >
            {isAnalyzing ? <Loader2 className="animate-spin w-4 h-4" /> : <Sparkles size={16} />}
          </button>
        </div>
        <div className="p-4 flex-1 overflow-y-auto bg-indigo-50/30">
          {analysis ? (
            <div className="prose prose-sm max-w-none text-slate-700">
              <div className="flex justify-end mb-2">
                <button onClick={() => handleSpeak(analysis)} className="text-indigo-600 hover:text-indigo-800">
                  <Volume2 size={16} />
                </button>
              </div>
              <div className="whitespace-pre-wrap">{analysis}</div>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-full text-center p-6 text-indigo-300">
              <Sparkles size={48} className="mb-4 opacity-20" />
              <p className="text-sm">Click the spark icon to generate AI trends analysis from your records.</p>
            </div>
          )}
        </div>
      </div>

      {/* Chat Assistant */}
      <div className={`${isExpanded ? 'lg:col-span-1' : 'lg:col-span-2'} bg-white rounded-xl shadow-lg flex flex-col h-[600px] border border-indigo-100`}>
        <div className="p-4 bg-slate-800 rounded-t-xl text-white flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-indigo-500 rounded-full flex items-center justify-center">
              <Bot size={20} />
            </div>
            <div>
              <h3 className="font-bold leading-none">Nursing Audit Assistant</h3>
              <p className="text-[10px] text-slate-400 mt-1 uppercase tracking-wider">Powered by Gemini Pro</p>
            </div>
          </div>
          <button onClick={() => setIsExpanded(!isExpanded)} className="text-slate-400 hover:text-white">
            {isExpanded ? <Minimize2 size={18} /> : <Maximize2 size={18} />}
          </button>
        </div>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">
          {messages.length === 0 && (
            <div className="text-center py-10 text-slate-400">
              <p className="text-sm">Ask me anything about clinical audits, tracer standards, or nursing documentation.</p>
            </div>
          )}
          {messages.map((m, i) => (
            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[80%] p-3 rounded-2xl flex items-start gap-3 ${
                m.role === 'user' 
                  ? 'bg-indigo-600 text-white rounded-tr-none' 
                  : 'bg-white text-slate-800 shadow-sm border border-slate-200 rounded-tl-none'
              }`}>
                {m.role === 'model' && <Bot size={16} className="mt-1 flex-shrink-0" />}
                <div className="space-y-2">
                  <p className="text-sm whitespace-pre-wrap">{m.content}</p>
                  {m.role === 'model' && (
                    <button onClick={() => handleSpeak(m.content)} className="text-indigo-400 hover:text-indigo-600">
                      <Volume2 size={14} />
                    </button>
                  )}
                </div>
                {m.role === 'user' && <User size={16} className="mt-1 flex-shrink-0" />}
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-white p-3 rounded-2xl shadow-sm border border-slate-200 flex items-center gap-2">
                <Loader2 size={16} className="animate-spin text-indigo-600" />
                <span className="text-sm text-slate-400">Thinking...</span>
              </div>
            </div>
          )}
        </div>

        <div className="p-4 border-t bg-white rounded-b-xl">
          <div className="flex gap-2">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Type your question..."
              className="flex-1 p-2 bg-slate-100 border-none rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
            />
            <button 
              onClick={handleSend}
              disabled={isLoading || !input.trim()}
              className="p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 transition-all shadow-md"
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Assistant;

