import React, { useState } from 'react';
import { 
  MONTHS, 
  DEPARTMENTS, 
  RN_LEVELS, 
  SPECIALTIES, 
  SECTIONS_CONFIG 
} from '../constants';
import { ComplianceStatus, TracerRound, SectionData } from '../types';
import { Save, ChevronRight, ChevronLeft, PlusCircle, Database, FileText } from 'lucide-react';

interface TracerFormProps {
  onSubmit: (data: TracerRound) => void;
}

const TracerForm: React.FC<TracerFormProps> = ({ onSubmit }) => {
  const [step, setStep] = useState(0);
  const [formData, setFormData] = useState<Partial<TracerRound>>({
    year: new Date().getFullYear(),
    month: MONTHS[new Date().getMonth()],
    date: new Date().toISOString().split('T')[0],
    sourceOfData: '',
    depType: DEPARTMENTS[0].type,
    department: DEPARTMENTS[0].name,
    rnLevel: RN_LEVELS[0],
    principalDiagnosis: '',
    comorbidity: '',
    specialty: SPECIALTIES[0],
    patientAge: 0,
    sections: SECTIONS_CONFIG.reduce((acc, section) => {
      acc[section.id as keyof TracerRound['sections']] = {
        items: section.items.reduce((itemAcc, item) => {
          itemAcc[item.id] = ComplianceStatus.MET;
          return itemAcc;
        }, {} as Record<string, ComplianceStatus>),
        finding: ''
      };
      return acc;
    }, {} as TracerRound['sections']),
    developmentIssues: '',
    appreciations: ''
  });

  const handleBasicInfoChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;

    if (name === 'department') {
      const selectedDept = DEPARTMENTS.find(d => d.name === value);
      setFormData(prev => ({ 
        ...prev, 
        department: value,
        depType: selectedDept ? selectedDept.type : prev.depType
      }));
    } else {
      setFormData(prev => ({ 
        ...prev, 
        [name]: (name === 'year' || name === 'patientAge') ? (parseInt(value) || 0) : value 
      }));
    }
  };

  const handleStatusChange = (sectionId: string, itemId: string, status: ComplianceStatus) => {
    setFormData(prev => {
      const sections = { ...prev.sections } as TracerRound['sections'];
      sections[sectionId as keyof TracerRound['sections']].items[itemId] = status;
      return { ...prev, sections };
    });
  };

  const handleFindingChange = (sectionId: string, finding: string) => {
    setFormData(prev => {
      const sections = { ...prev.sections } as TracerRound['sections'];
      sections[sectionId as keyof TracerRound['sections']].finding = finding;
      return { ...prev, sections };
    });
  };

  const handleFinalSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalData: TracerRound = {
      ...formData as TracerRound,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    onSubmit(finalData);
  };

  const steps = [
    { title: 'Demographics', content: (
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">Year</label>
          <input type="number" name="year" value={formData.year} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2.5 bg-white border" />
        </div>
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">Month</label>
          <select name="month" value={formData.month} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2.5 bg-white border">
            {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">Date</label>
          <input type="date" name="date" value={formData.date} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2.5 bg-white border" />
        </div>
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">Source of Data</label>
          <input 
            type="text" 
            name="sourceOfData" 
            value={formData.sourceOfData} 
            onChange={handleBasicInfoChange} 
            placeholder="e.g. Medical Record, Interview"
            className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2.5 bg-white border" 
          />
        </div>
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">Department</label>
          <select name="department" value={formData.department} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2.5 bg-white border">
            {DEPARTMENTS.map(d => <option key={d.name} value={d.name}>{d.name}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">Department Type</label>
          <input type="text" name="depType" value={formData.depType} readOnly className="mt-1 block w-full rounded-md border-gray-200 shadow-sm sm:text-sm p-2.5 bg-gray-50 border cursor-not-allowed font-semibold text-indigo-700" />
        </div>
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">RN Level</label>
          <select name="rnLevel" value={formData.rnLevel} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2.5 bg-white border">
            {RN_LEVELS.map(l => <option key={l} value={l}>{l}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">Specialty</label>
          <select name="specialty" value={formData.specialty} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2.5 bg-white border">
            {SPECIALTIES.map(s => <option key={s} value={s}>{s}</option>)}
          </select>
        </div>
        <div className="md:col-span-2">
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">Principal Diagnosis</label>
          <input type="text" name="principalDiagnosis" value={formData.principalDiagnosis} onChange={handleBasicInfoChange} placeholder="Enter main diagnosis" className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2.5 bg-white border" />
        </div>
        <div className="md:col-span-2">
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">Comorbidity</label>
          <input type="text" name="comorbidity" value={formData.comorbidity} onChange={handleBasicInfoChange} placeholder="Enter secondary conditions" className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2.5 bg-white border" />
        </div>
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">Patient Age (Years)</label>
          <input type="number" name="patientAge" value={formData.patientAge} onChange={handleBasicInfoChange} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2.5 bg-white border" />
        </div>
      </div>
    )},
    ...SECTIONS_CONFIG.map(section => ({
      title: section.title,
      content: (
        <div className="space-y-6">
          <div className="bg-indigo-50 p-4 rounded-xl flex items-center gap-3 mb-4 border border-indigo-100">
            <div className="text-indigo-600">
              {section.icon}
            </div>
            <h3 className="font-bold text-indigo-900">{section.title}</h3>
          </div>
          <div className="bg-white rounded-xl border border-gray-100 overflow-hidden">
            {section.items.map(item => (
              <div key={item.id} className="flex flex-col md:flex-row md:items-center justify-between p-4 border-b border-gray-50 last:border-0 hover:bg-gray-50 transition-colors">
                <span className="text-sm text-gray-700 font-medium mb-3 md:mb-0 leading-relaxed pr-4 flex items-start gap-2">
                  <span className="text-indigo-400 font-mono text-xs mt-0.5">{item.id}</span>
                  {item.label}
                </span>
                <div className="flex gap-1.5 flex-wrap md:flex-nowrap justify-end">
                  {[ComplianceStatus.MET, ComplianceStatus.PARTIALLY_MET, ComplianceStatus.NOT_MET, ComplianceStatus.NA].map(status => (
                    <button
                      key={status}
                      type="button"
                      onClick={() => handleStatusChange(section.id, item.id, status)}
                      className={`px-3 py-1.5 text-[10px] font-bold rounded-lg border transition-all whitespace-nowrap uppercase tracking-tighter ${
                        formData.sections?.[section.id as keyof TracerRound['sections']]?.items[item.id] === status
                          ? status === ComplianceStatus.MET ? 'bg-green-600 text-white border-green-600 shadow-sm' :
                            status === ComplianceStatus.PARTIALLY_MET ? 'bg-amber-500 text-white border-amber-500 shadow-sm' :
                            status === ComplianceStatus.NOT_MET ? 'bg-red-600 text-white border-red-600 shadow-sm' :
                            'bg-slate-500 text-white border-slate-500 shadow-sm'
                          : 'bg-white text-gray-400 border-gray-200 hover:border-indigo-300 hover:text-indigo-600'
                      }`}
                    >
                      {status}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
          <div className="mt-6">
            <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">Findings / Comments for this section</label>
            <textarea
              value={formData.sections?.[section.id as keyof TracerRound['sections']]?.finding}
              onChange={(e) => handleFindingChange(section.id, e.target.value)}
              className="w-full h-24 p-4 border border-gray-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm leading-relaxed"
              placeholder="Record any specific observations, patient quotes, or missed documentation..."
            />
          </div>
        </div>
      )
    })),
    { title: 'Final Summary', content: (
      <div className="space-y-6">
        <div>
          <label className="flex items-center gap-2 text-sm font-bold text-red-600 mb-2">
            <PlusCircle size={16} /> Development Issues (Areas for Improvement)
          </label>
          <textarea
            name="developmentIssues"
            value={formData.developmentIssues}
            onChange={handleBasicInfoChange}
            className="w-full h-32 p-4 border border-red-100 bg-red-50/10 rounded-xl focus:ring-2 focus:ring-red-500 outline-none text-sm"
            placeholder="Document gaps in care, medication errors, or safety risks..."
          />
        </div>
        <div>
          <label className="flex items-center gap-2 text-sm font-bold text-green-600 mb-2">
            <PlusCircle size={16} /> Appreciations (Commendations)
          </label>
          <textarea
            name="appreciations"
            value={formData.appreciations}
            onChange={handleBasicInfoChange}
            className="w-full h-32 p-4 border border-green-100 bg-green-50/10 rounded-xl focus:ring-2 focus:ring-green-500 outline-none text-sm"
            placeholder="Note excellent communication, neat clinical records, or patient praise..."
          />
        </div>
      </div>
    )}
  ];

  return (
    <div className="max-w-4xl mx-auto bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-200">
      <div className="bg-slate-900 p-8 text-white">
        <div className="flex justify-between items-center mb-6">
          <div>
            <div className="flex items-center gap-2 text-indigo-400 font-bold tracking-widest text-[10px] uppercase mb-1">
              <Database size={12} /> New Audit Entry
            </div>
            <h2 className="text-2xl font-bold">Nursing Tracer Round</h2>
          </div>
          <div className="text-right">
            <div className="text-[10px] text-slate-400 uppercase font-bold tracking-widest mb-1">Progress</div>
            <span className="text-lg font-mono font-bold text-indigo-300">
              {Math.round(((step + 1) / steps.length) * 100)}%
            </span>
          </div>
        </div>
        <div className="w-full bg-slate-800 h-1.5 rounded-full overflow-hidden">
          <div 
            className="bg-indigo-500 h-full transition-all duration-500 ease-out" 
            style={{ width: `${((step + 1) / steps.length) * 100}%` }}
          />
        </div>
      </div>

      <div className="p-8">
        <div className="flex items-center gap-2 mb-8">
          <div className="w-1 h-6 bg-indigo-600 rounded-full"></div>
          <h3 className="text-xl font-bold text-slate-900">{steps[step].title}</h3>
        </div>

        <div className="min-h-[400px]">
          {steps[step].content}
        </div>

        <div className="mt-12 pt-8 border-t border-slate-100 flex justify-between items-center">
          <button
            type="button"
            onClick={() => setStep(s => Math.max(0, s - 1))}
            disabled={step === 0}
            className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-bold transition-all ${
              step === 0 ? 'text-slate-300 cursor-not-allowed' : 'text-slate-600 hover:bg-slate-100 active:scale-95'
            }`}
          >
            <ChevronLeft size={20} /> Previous
          </button>

          {step < steps.length - 1 ? (
            <button
              type="button"
              onClick={() => setStep(s => s + 1)}
              className="flex items-center gap-2 px-10 py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-100 active:scale-95 transition-all"
            >
              Next Step <ChevronRight size={20} />
            </button>
          ) : (
            <button
              type="button"
              onClick={handleFinalSubmit}
              className="flex items-center gap-2 px-10 py-3 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 shadow-lg shadow-green-100 active:scale-95 transition-all"
            >
              <Save size={20} /> Save Audit Record
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

