const HistoryView = ({ rounds }: { rounds: TracerRound[] }) => {
  const [selectedRoundSummary, setSelectedRoundSummary] = useState<{id: string, text: string} | null>(null);
  const [summarizingId, setSummarizingId] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  const handleGenerateSummary = async (round: TracerRound) => {
    if (summarizingId) return;
    setSummarizingId(round.id);
    try {
      const summary = await analyzeSingleRound(round);
      setSelectedRoundSummary({ id: round.id, text: summary });
    } catch (err) {
      alert("Failed to generate summary. Please try again.");
    } finally {
      setSummarizingId(null);
    }
  };

  const copyToClipboard = () => {
    if (selectedRoundSummary) {
      navigator.clipboard.writeText(selectedRoundSummary.text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="max-w-6xl mx-auto">
      {selectedRoundSummary && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl overflow-hidden border border-slate-200 animate-in fade-in zoom-in duration-300">
            <div className="p-6 bg-slate-900 text-white flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-indigo-500/20 rounded-xl">
                  <Sparkles className="text-indigo-400" size={24} />
                </div>
                <div>
                  <h3 className="font-bold text-xl">Audit Executive Summary</h3>
                  <p className="text-[10px] text-slate-400 uppercase tracking-widest font-bold">Generated by Gemini Clinical AI</p>
                </div>
              </div>
              <button onClick={() => setSelectedRoundSummary(null)} className="text-slate-400 hover:text-white p-2 hover:bg-slate-800 rounded-full transition-colors">
                <X size={24} />
              </button>
            </div>
            <div className="p-8 overflow-y-auto max-h-[60vh] bg-slate-50/50">
              <div className="prose prose-indigo prose-sm max-w-none text-slate-700 whitespace-pre-wrap leading-relaxed font-medium">
                {selectedRoundSummary.text}
              </div>
            </div>
            <div className="p-6 bg-white border-t border-slate-100 flex justify-between items-center">
              <button 
                onClick={copyToClipboard}
                className="flex items-center gap-2 px-4 py-2 bg-slate-100 text-slate-600 rounded-xl font-bold hover:bg-slate-200 transition-all text-sm"
              >
                {copied ? <Check size={18} className="text-green-600" /> : <Copy size={18} />}
                {copied ? 'Copied' : 'Copy Summary'}
              </button>
              <button 
                onClick={() => setSelectedRoundSummary(null)}
                className="px-8 py-2.5 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100 active:scale-95"
              >
                Close Report
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-6 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
          <div>
            <h3 className="text-lg font-bold text-slate-900">Historical Round Records</h3>
            <p className="text-xs text-slate-500 mt-0.5">Comprehensive list of all nursing tracer rounds</p>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-xs font-bold text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-100">
              {rounds.length} Total Audits
            </span>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-500 text-[10px] uppercase tracking-widest font-bold">
                <th className="px-6 py-4">Date & Source</th>
                <th className="px-6 py-4">Department</th>
                <th className="px-6 py-4">Diagnosis</th>
                <th className="px-6 py-4">Staff Level</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {rounds.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center">
                    <div className="flex flex-col items-center justify-center text-slate-400">
                      <FileText size={48} className="mb-4 opacity-20" />
                      <p className="text-sm font-medium">No records found.</p>
                      <Link to="/new" className="mt-2 text-indigo-600 text-xs font-bold hover:underline">Create your first audit round</Link>
                    </div>
                  </td>
                </tr>
              ) : (
                rounds.map(round => (
                  <tr key={round.id} className="hover:bg-indigo-50/20 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="text-sm font-bold text-slate-900">{round.date}</div>
                      <div className="text-[10px] text-slate-400 truncate max-w-[150px]">{round.sourceOfData || 'N/A'}</div>
