                    <td className="px-6 py-4">
                      <span className="bg-indigo-50 text-indigo-700 px-2 py-1 rounded text-[10px] font-bold border border-indigo-100 uppercase">
                        {round.rnLevel}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex items-center justify-end gap-2 opacity-100 lg:opacity-0 group-hover:opacity-100 transition-all translate-x-0 lg:translate-x-2 group-hover:translate-x-0">
                        <button 
                          onClick={() => handleGenerateSummary(round)}
                          disabled={summarizingId === round.id}
                          className={`flex items-center gap-1.5 text-[10px] font-bold px-3 py-1.5 rounded-xl border transition-all ${
                            summarizingId === round.id 
                            ? 'bg-slate-100 text-slate-400 border-slate-200' 
                            : 'bg-indigo-50 text-indigo-600 border-indigo-100 hover:bg-indigo-600 hover:text-white shadow-sm hover:shadow-indigo-200'
                          }`}
                        >
                          {summarizingId === round.id ? (
                            <Loader2 size={12} className="animate-spin" />
                          ) : (
                            <Sparkles size={12} className="group-hover:animate-pulse" />
                          )}
                          AI SUMMARY
                        </button>
                        <Link to={`/history/${round.id}`} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all">
                          <ChevronRight size={20} />
                        </Link>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

