            <Route path="/new" element={<TracerForm onSubmit={handleAddRound} />} />
            <Route path="/history" element={<HistoryView rounds={rounds} />} />
            <Route path="/history/:id" element={<ReportView rounds={rounds} />} />
            <Route path="/assistant" element={
              <div className="max-w-6xl mx-auto space-y-6">
                <div>
                  <h2 className="text-3xl font-bold text-slate-900 tracking-tight">Clinical Assistant</h2>
                  <p className="text-slate-500 font-medium">Expert guidance on audit findings and patient safety</p>
                </div>
                <Assistant rounds={rounds} />
              </div>
            } />
            <Route path="/settings" element={<SettingsView rounds={rounds} onUpdateRounds={handleUpdateRounds} />} />
          </Routes>
        </div>
      </main>
    </div>
  );
};

