const SettingsView = ({ rounds, onUpdateRounds }: { rounds: TracerRound[], onUpdateRounds: (rounds: TracerRound[]) => void }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const exportToJson = () => {
    const dataStr = JSON.stringify(rounds, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,' + encodeURIComponent(dataStr);
    const exportFileDefaultName = `nursing-tracer-backup-${new Date().toISOString().split('T')[0]}.json`;

    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  const exportToCsv = () => {
    if (rounds.length === 0) {
      alert("No data to export.");
      return;
    }

    const headers = ["ID", "Date", "Department", "Dept Type", "RN Level", "Diagnosis", "Specialty", "Age"];
    SECTIONS_CONFIG.forEach(s => headers.push(`${s.title} Score`));
    headers.push("Issues", "Appreciations");

    const rows = rounds.map(r => {
      const row = [
        r.id.slice(0, 8),
        r.date,
        `"${r.department}"`,
        r.depType,
        r.rnLevel,
        `"${r.principalDiagnosis.replace(/"/g, '""')}"`,
        `"${r.specialty}"`,
        r.patientAge
      ];

      SECTIONS_CONFIG.forEach(section => {
        const sData = r.sections[section.id as keyof TracerRound['sections']];
        let scoreSum = 0;
        let totalItems = 0;
        Object.values(sData.items).forEach(status => {
          if (status !== ComplianceStatus.NA) {
            totalItems++;
            if (status === ComplianceStatus.MET) scoreSum += 1;
            else if (status === ComplianceStatus.PARTIALLY_MET) scoreSum += 0.5;
          }
        });
        const pct = totalItems > 0 ? Math.round((scoreSum / totalItems) * 100) : 0;
        row.push(`${pct}%`);
      });

      row.push(`"${r.developmentIssues.replace(/"/g, '""')}"`);
      row.push(`"${r.appreciations.replace(/"/g, '""')}"`);
      return row.join(",");
    });

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(","), ...rows].join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `nursing-tracer-report-${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const result = e.target?.result as string;
        const json = JSON.parse(result);

        if (Array.isArray(json)) {
          const validRecords = json.filter(item => 
            item && 
            typeof item === 'object' && 
            item.id && 
            item.sections && 
            typeof item.sections === 'object'
          );

          if (validRecords.length === 0 && json.length > 0) {
            alert("The uploaded file does not contain valid Nursing Tracer records.");
            return;
          }

          const existingIds = new Set(rounds.map(r => r.id));
          const uniqueNewRecords = validRecords.filter(r => !existingIds.has(r.id));

          if (uniqueNewRecords.length === 0) {
            alert("All records in this backup already exist in your history.");
            return;
          }

          const merged = [...uniqueNewRecords, ...rounds];
          onUpdateRounds(merged);
          alert(`Success! Imported ${uniqueNewRecords.length} new records and skipped ${validRecords.length - uniqueNewRecords.length} duplicates.`);
        } else {
          alert("Import failed: The file must be a JSON array of records.");
        }
      } catch (err) {
        alert("Error parsing backup file. Please ensure it is a valid JSON file exported from this application.");
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const clearAllData = () => {
    if (confirm("ARE YOU SURE? This will permanently delete all audit records. This action cannot be undone.")) {
      onUpdateRounds([]);
      alert("All data has been cleared.");
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      <div>
        <h2 className="text-2xl font-bold text-slate-900">System Settings & Data Management</h2>
        <p className="text-slate-500">Manage your clinical audit database, exports, and backups.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-2 bg-indigo-50 text-indigo-600 rounded-lg">
              <Download size={24} />
            </div>
            <h3 className="text-lg font-bold text-slate-900">Export Data</h3>
          </div>
          <div className="space-y-4">
            <button 
              onClick={exportToCsv}
              className="w-full flex items-center justify-between p-4 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded-xl transition-all group"
            >
              <div className="flex items-center gap-3">
                <FileSpreadsheet className="text-green-600" />
                <div className="text-left">
                  <p className="font-bold text-slate-900 text-sm">Export to CSV (Excel)</p>
                  <p className="text-xs text-slate-500">Summarized report for spreadsheet analysis</p>
                </div>
              </div>
              <ChevronRight size={18} className="text-slate-300 group-hover:text-indigo-600 transition-colors" />
            </button>
            <button 
              onClick={exportToJson}
              className="w-full flex items-center justify-between p-4 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded-xl transition-all group"
            >
              <div className="flex items-center gap-3">
                <FileJson className="text-indigo-600" />
                <div className="text-left">
                  <p className="font-bold text-slate-900 text-sm">Full Backup (JSON)</p>
                  <p className="text-xs text-slate-500">High-fidelity backup of all audit details</p>
                </div>
              </div>
              <ChevronRight size={18} className="text-slate-300 group-hover:text-indigo-600 transition-colors" />
            </button>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-2 bg-amber-50 text-amber-600 rounded-lg">
              <Upload size={24} />
            </div>
            <h3 className="text-lg font-bold text-slate-900">Restore & Upload</h3>
          </div>
          <p className="text-sm text-slate-500 mb-6">
            Upload a previously exported JSON backup to merge records into your current local database. 
