                      {summaryState.content ? 'AI ANALYSIS' : (lang === 'en' ? 'SUMMARIZE WITH AI' : 'สรุปด้วย AI')}
                      {summaryState.content && (summaryState.expanded ? <ChevronUp size={12} /> : <ChevronDown size={12} />)}
