            if (field === 'finding') entry.sections[sectionId].finding = val;
            else entry.sections[sectionId].items[field] = val;
          } else {
            if (['year', 'patientAge', 'createdAt'].includes(key)) entry[key] = parseInt(val) || 0;
            else entry[key] = val;
          }
        });
        if (!entry.id) entry.id = crypto.randomUUID();
        if (!entry.createdAt) entry.createdAt = Date.now();
        newRounds.push(entry as TracerRound);
      });

      if (newRounds.length > 0) {
